:root {
  --paper: #fffdf5;
  --ink: #24342c;
  --leaf: #4d7656;
  --sprout: #dce8c8;
  --clay: #c96846;
}

.seed-slip {
  box-sizing: border-box;
  width: 476px;
  padding: 16px;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.slip-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--sprout);
}

.seed-mark {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 50%;
  background: var(--leaf);
  color: var(--paper);
}

.eyebrow {
  margin: 0;
  flex: 1;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.status {
  padding: 4px 7px;
  border-radius: 5px;
  background: var(--sprout);
  color: var(--leaf);
  font-size: 10px;
  font-weight: 700;
}

.slip-body {
  padding: 16px 0;
}

.slip-body h1 {
  margin: 0 0 4px;
  font-size: 22px;
  line-height: 1.1;
}

.detail {
  margin: 0;
  color: var(--leaf);
  font-size: 14px;
}

.slip-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 10px;
  border-top: 1px solid var(--sprout);
  color: var(--leaf);
  font-size: 12px;
}

.slip-footer button {
  border: 0;
  border-radius: 6px;
  padding: 7px 11px;
  background: var(--clay);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}
